/**
 * Auto-generated digest of upstream's per-shot notes and aesthetic rules
 * from .claude/skills/video-shotcraft/references/.
 *
 * Appended to director/edit prompts so the AI director plans shots, copy,
 * colour, timing and music the way upstream's validated templates do.
 */
export const AESTHETIC_DIGEST = "Upstream aesthetic rules digest (video-shotcraft references):\n• 审美准则（判例式）\n  • 节奏（R）\n    • R1. 关键信息落定后必须呼吸，品牌字标 hold 满 1 秒\n    • R2. 速度感来自加速度，不是匀速快；群体运动挂物理隐喻，收尾留 0.5s 停顿\n    • R3. 节奏宁慢勿快：初版默认放慢一档，主体动作弧 ≥3s，交互演示按真人操作速度\n    • R4. 卡点约束时机不放大幅度：全画面级节拍冲击全片 ≤3 处，默认只动元素层\n  • 质感·运镜·构图（Q）\n    • Q1. 复刻既有页面必须真实截图；手搓 UI 限非复刻场景且质量/表达达标；数据按风险口径处理\n    • Q2. 3D 透视下 UI 纹理按原生尺寸 rasterize 后缩小使用；文字发糊先查纹理分辨率链路\n    • Q3. 镜头要稳：产品宣传片默认不加手持抖动\n    • Q4. 高光/扫光特效宁缺毋滥：不群发，一个镜头最多给主角一次，且必须裁进圆角边界\n    • Q5. 开场只给一个主角：单主体 + 完整动作弧，胜过群体群舞\n    • Q6. 机位服务可读性：信息密集镜头正视，文字特写侧向水平，风格化倾斜逐镜头验证\n    • Q7. 物件特写四件套：侧面倾斜角 + 可感知高度 + orbit 环绕 + 反差深色材质背景\n    • Q8. 结尾做成\"发布会合影\"：全片元素四方飞入围住字标，能量推到全片峰值\n    • Q9. 飞入动画的终点必须是页面布局里的真实槽位，元素不悬浮在页面上方\n    • Q10. 文档类镜头的 mock 内容要出版级：原生排版、文字铺满、完整版式入镜\n    • Q11. 要被读的文字有最低有效字高：字幕 ≥5% 帧高，辅助文字 ≥3%；按最终像素量，不按 fontSize\n  • 声音（S）\n    • S1. 配乐与音效按\"片种\"选，不按\"事件\"选：强鼓点电子底 + 电影系 SFX 词汇，禁游戏音包音色（禁音色不禁动作）\n    • S2. SFX 逐拍钉帧管理；连发音效做双样本交替 + 音量阶梯递减 + 间隔加速，不同响度复读\n    • S3. 声音在画面锁定后做；时间线一动，SFX 全表重钉\n    • S4. 拟音优先于装饰音：画面动作配该动作的真实声音，音频裁到与动作严格等长\n    • S5. 音画对齐补两项偏移：输出音轨偏移逐渲染管线实测统一扣，音源峰值滞后逐文件量\n  • 文案（C）\n    • C1. 文案在画面锁定后按最终镜头重写一遍，纯动画段落也配解说\n    • C2. 标语写\"团队 + 产品功能名 + 具体收益\"，抽象隐喻词一律具体化\n    • C3. 3D 镜头里的注记文字活在同一 3D 空间：page-space、同透视、斜拍，大字 + 荧光笔 highlight\n  • 流程（P）\n    • P1. 交付前必须自己渲染截帧逐一检查，不把首检交给用户\n    • P2. 参考素材先逐帧拆解成手法清单，再逐镜头判断适配性，不全局套用\n    • P3. 指代含糊的反馈先确认对象；改错了整 commit 干净 revert，不在错误版本上打补丁\n    • P4. 先列功能清单逐一对应镜头；一种动画手法全片只当一次主角，重复镜头/信息一律删\n• pipeline — 八阶段制作流水线\n  • 阶段 0：产品理解与执行约束\n  • 阶段 1：视觉方向与 styleframe\n  • 阶段 2：功能到镜头映射\n  • 阶段 3：分镜与制作放行\n  • 阶段 4：最终素材采集\n  • 阶段 5：逐镜头实现\n  • 阶段 6：声音设计\n  • 阶段 7：验收\n• sound-design — 声音设计\n  • 1. 方法\n  • 2. BGM 选型\n    • 演进：三易其稿（34 分钟）\n    • 选型判据（从用户原话反推）\n    • 免费授权来源清单\nApply these to every plan and edit: prefer real captured pages over mock UI, one hero per opening shot, stable camera (no handheld shake), titles/captions ≥ legible size, copy written after picture lock, SFX nailed to the beat and frame-accurate, music chosen by piece not event, flash cuts ≤3 per film, end with a launch call to action, and render + inspect every frame before delivery.";

/** Returns the digest appended with a short instruction to the director. */
export const aestheticDigest = (): string => AESTHETIC_DIGEST;
